export function initVideo(){const e=[...document.querySelectorAll(".element-wrapper img")],t=e=>{const t=e.dataset.id,n=e.closest(".element-wrapper"),o=(e=>{const t=document.createElement("iframe");return t.src=`https://www.tiktok.com/embed/${e}`,t.width=325,t.height="100%",t.loading="lazy",t})(t);n.textContent="",n.appendChild(o)};for(let n of e)n.addEventListener("click",(()=>t(n)))}